-- SGU MSA website: the database, part 2 of 4 (starter data). Run after 202610150001_schema.sql and before
-- 202610150004_recent_changes.sql, so none of these rows shows in Recent changes. Sample-free: no people,
-- logins, events or money; the board adds the real ones from the dashboard.

-- The founder's three team groups (user, 2026-10-05). The Executive board and the General board always
-- exist; "Show on public page?" starts as Yes for a new person in the Executive board, No elsewhere.
insert into public.people_sections (name, position, kind, shown_by_default)
values ('Executive board', 1, 'executive', true), ('General board', 2, 'general', false),
  ('Advisors/Faculty', 3, null, false);

-- The one prayer settings row (no schedule yet: the board sets the iqamah times).
insert into public.prayer_settings(id) values (1);

-- The starting pin: the Google Maps place "MSA Mosque" the user gave (PR7, 2026-10-04, D-3). The board
-- confirms it on site (release checklist).
insert into public.musallah_location (id, latitude, longitude) values (1, 12.0025521, -61.7723834);

-- New board term: the starter hand-over steps (wording from the approved hand-over mockup, PR5a).
insert into public.handover_steps (title, details, link, position) values
  ('Invite the new board',
   'People → Add → Send invite. Give “manage people” to at least two.', '/admin/people', 1),
  ('Turn off leaving members’ logins',
   'Deactivate, or archive if they also leave the team list.', '/admin/people', 2),
  ('Update the team list',
   'Role titles, order, groups and “Show on public page?”.', '/admin/people', 3),
  ('Change shared passwords',
   'Instagram, MSA Gmail, Go2Pay. Then set “Last changed” below. Never write passwords here.', '', 4),
  ('Check content',
   'Upcoming events, iqamah end date, Hijri date setting, old notices.', '/admin/prayer-times', 5),
  ('Tell the site owner who the new board is',
   'Website accounts and the MSA Gmail keep two owners with recovery access.', '', 6);

-- Starter seasons (PR6 D-15). Ramadan's page (PR5c) starts from the text and photos of the old Ramadan page.
insert into public.seasons (name, hijri_month, hijri_first_day, hijri_last_day, slug) values
  ('Eid al-Fitr', 10, 1, 1, 'eid-al-fitr'),
  ('Eid al-Adha', 12, 10, 10, 'eid-al-adha');
insert into public.seasons (name, hijri_month, hijri_first_day, hijri_last_day, slug, has_page, intro, schedule,
  sign_up_form, photos) values
  ('Ramadan', 9, 1, null, 'ramadan', true,
   $seed$A month of worship, community, service, and gratitude.

Setting up iftar, organizing the Musallah, and helping run nightly programmes — there is a place for every level of availability.$seed$,
   $seed$[{"what": "Community iftar", "when": "To be confirmed", "where": ""},
     {"what": "Tarawih at the Musallah", "when": "To be confirmed", "where": ""},
     {"what": "Qiyam nights", "when": "To be confirmed", "where": ""},
     {"what": "Ramadan halaqa series", "when": "To be confirmed", "where": ""}]$seed$::jsonb,
   'ramadan_volunteer',
   $seed$[{"src": "/images/ramadan/hero-lanterns.webp", "alt": "Ramadan Mubarak sign lit by candlelight inside the SGU Musallah"},
     {"src": "/images/ramadan/gallery-mubarak-sign.webp", "alt": "A Ramadan Mubarak sign set up by the MSA inside the Musallah"},
     {"src": "/images/ramadan/gallery-isra-miraj.webp", "alt": "MSA programme graphic for a Night of Al-Isra’ Wal-Mi‘raj halaqa"},
     {"src": "/images/ramadan/gallery-halaqa.webp", "alt": "MSA halaqa graphic: Ramadan on the Island — Balancing Ibadah and Academia"},
     {"src": "/images/ramadan/gallery-bake-sale.webp", "alt": "MSA bake sale graphic raising funds ahead of Ramadan"}]$seed$::jsonb);

-- Starter merch: the three collections of the old Merch page, one shirt each, no sizes yet (PR5c).
with collection as (
  insert into public.merch_collections (name, arabic, quote, year, description, era, position) values
    ('Green Collection', 'قلب سليم',
     'No act of devotion is accepted until the heart of the worshipper is cleansed of false belief and ill intention.',
     '', 'The first MSA collection.', 'past', 1),
    ('Maroon Collection', 'حيث تطمئن القلوب', 'In remembrance, hearts find ease.', '',
     '', 'past', 2),
    ('Shukr', 'شكر', 'Give thanks in ease and in hardship, for what reaches you is by decree.', '',
     'The current MSA collection.', 'current', 3)
  returning id, position
)
insert into public.merch_items (collection_id, name, description, garment, colorway, photos, position)
select collection.id, item.name, item.description, 'Long-sleeve', item.colorway, item.photos::jsonb, 1
from collection join (values
  (1, 'Green long-sleeve',
   'A dark green long-sleeve carrying the sound heart — a reminder that intention comes before action.',
   'Forest green',
   $seed$[{"src": "/images/merch/green-order-sheet.webp", "alt": "SGU MSA green long-sleeve order sheet showing the Qalb Saleem front design"}]$seed$),
  (2, 'Maroon long-sleeve',
   'A maroon long-sleeve with an arched mosque and tree printed across the back, worn across campus and the island.',
   'Maroon',
   $seed$[{"src": "/images/merch/maroon-waterfront.webp", "alt": "Two students in the maroon MSA long-sleeve seated at the waterfront, the back print visible"},
     {"src": "/images/merch/maroon-order-sheet.webp", "alt": "Maroon MSA long-sleeve order sheet showing the front and back of the shirt"},
     {"src": "/images/merch/maroon-back-detail.webp", "alt": "Close view of the arch and tree print on the back of the maroon long-sleeve"},
     {"src": "/images/merch/maroon-full.webp", "alt": "Students wearing the maroon MSA long-sleeve on campus"}]$seed$),
  (3, 'Shukr long-sleeve',
   'A navy long-sleeve carrying Shukr across the back beneath a stamp panel — gratitude as the posture a student keeps in both directions.',
   'Navy',
   $seed$[{"src": "/images/merch/shukr-back.webp", "alt": "The Shukr back print on the navy MSA long-sleeve, worn by two students"},
     {"src": "/images/merch/shukr-front.webp", "alt": "Front of the navy Shukr long-sleeve with the MSA crest at the chest"},
     {"src": "/images/merch/shukr-detail.webp", "alt": "Detail of the Shukr stamp panel printed on the back of the long-sleeve"},
     {"src": "/images/merch/shukr-full.webp", "alt": "A student wearing the navy Shukr long-sleeve on the campus field"},
     {"src": "/images/merch/shukr-pair.webp", "alt": "Two students wearing the navy Shukr long-sleeve on campus"}]$seed$)
) as item(position, name, description, colorway, photos) on item.position = collection.position;

-- The starter page text: generated by scripts/page-text-seed.mjs from content/*.yaml when the dashboard took
-- the page text over (PR5b), with the board's later starter changes (each document passes its schema and
-- the board's save rules). After this the live site owns its text; editing the YAML changes only the sandbox.
insert into public.page_texts (key, document) values ('home', $seed${"sections":[{"id":"week","shown":true},{"id":"contribution","shown":true},{"id":"updates","shown":true},{"id":"visit","shown":true},{"id":"features","shown":true},{"id":"faq","shown":true},{"id":"giving","shown":true}],"hero":{"eyebrow":"Faith. Knowledge. Community.","headline":"A little closer.","emphasis":"To faith. To each other.","body":["A place for prayer, growth, and brotherhood & sisterhood.","Welcome to your Muslim home away from home."],"image":{"src":"/images/community/island-landscape.webp","alt":"The Grenada coastline near the SGU campus","focal_point":"50% 50%","historical":false},"primary_cta":{"label":"What’s happening","href":"/calendar"},"secondary_cta":{"label":"Find the Musallah","href":"/prayer#find-the-musallah"},"aside":{"arabic":"شكر","transliteration":"Shukr","quote":"Give thanks in ease and in hardship, for what reaches you is by decree."}},"week":{"heading":"Upcoming at MSA","empty_message":"No public events currently listed."},"visit":{"image":{"src":"/images/prayer/musallah-interior.webp","alt":"Inside the SGU Musallah","historical":false}},"contribution":{"heading":"Our community, built by students","items":[{"id":"musallah-helper","title":"Become a Musallah Helper","short_description":"Help maintain our Musallah and facilities.","icon":"help","href":"/get-involved#musallah-helper"},{"id":"student-khutbah","title":"Give a Student Khutbah","short_description":"Share a khutbah as a student.","icon":"mic","href":"/get-involved#student-khutbah"},{"id":"host-halaqa","title":"Host a Halaqa","short_description":"Lead or host an Islamic gathering.","icon":"halaqa","href":"/get-involved#host-halaqa"},{"id":"volunteer","title":"Volunteer","short_description":"Serve at events and initiatives.","icon":"volunteer","href":"/get-involved#volunteer"},{"id":"mentor","title":"Mentor","short_description":"Guide an incoming or new student.","icon":"mentor","href":"/get-involved#mentor"},{"id":"support-ramadan","title":"Support Ramadan","short_description":"Donate or sponsor Ramadan programs.","icon":"package","href":"/donate"}]},"features":[{"id":"ramadan","eyebrow":"Seasonal community","title":"Ramadan at SGU","description":"Schedules, iftars, volunteering and donations.","href":"/ramadan","cta":"Visit Ramadan hub","image":{"src":"/images/ramadan/hero-lanterns.webp","alt":"Ramadan Mubarak sign lit by candlelight inside the SGU Musallah","focal_point":"40% 50%","historical":true}},{"id":"shukr","eyebrow":"MSA collection","title":"The Shukr Collection","description":"Wear your identity. Support your community.","href":"/merch","cta":"View merch","image":{"src":"/images/merch/shukr-back.webp","alt":"The Shukr back print on the navy MSA long-sleeve","focal_point":"50% 40%","historical":false}},{"id":"newsletter","eyebrow":"Newsletter archive","title":"Community newsletters","description":"Published updates, reminders, and stories from the MSA.","href":"/resources?category=newsletter","cta":"Browse newsletters","image":{"src":"/images/community/island-landscape.webp","alt":"The Grenada coastline near the SGU campus","focal_point":"50% 55%","historical":false}}]}$seed$::jsonb);
insert into public.page_texts (key, document) values ('about', $seed${"sections":[{"id":"mission","shown":true},{"id":"what_we_do","shown":true},{"id":"team","shown":true},{"id":"at_sgu","shown":true},{"id":"contact","shown":true}],"hero":{"eyebrow":"Who we are","title":"About SGU MSA","description":"Your Muslim home away from home."},"mission":{"heading":"Our Mission","body":["The SGU Muslim Students Association exists so that no Muslim student at St. George’s University has to choose between their studies and their deen.","We keep a place to pray, a calendar worth showing up to, and a community that notices when someone is missing. Everything the MSA does is organized by students, for students, on an island most of us arrived at alone."]},"what_we_do":{"heading":"What We Do","items":[{"id":"prayer","title":"Prayer & Jumu’ah","description":"Daily iqamah times and weekly Jumu’ah at the SGU Musallah.","icon":"prayer"},{"id":"learning","title":"Halaqas & Quran","description":"Weekly circles for study, recitation, and discussion.","icon":"book"},{"id":"ramadan","title":"Ramadan","description":"Iftars, tarawih, and nightly programming through the month.","icon":"moon"},{"id":"community","title":"Community","description":"Socials, sports, and the banquet that closes out the year.","icon":"community"},{"id":"service","title":"Service","description":"Fundraising and outreach beyond the campus gates.","icon":"volunteer"},{"id":"newcomers","title":"New Students","description":"Mentorship and orientation for students arriving at SGU.","icon":"graduation"}]},"board":{"heading":"Our team","note":"The MSA board is elected by students each year.","pending_label":"Board roster to be confirmed."},"at_sgu":{"heading":"MSA at SGU","body":["St. George’s University sits above True Blue Bay in Grenada, and draws students from more countries than most campuses many times its size. The MSA has been part of that campus for years — through Musallah moves, construction closures, and every intake of new students who arrive looking for the prayer room on their first Friday.","The organization is recognized as a student organization at SGU. Programming, funding, and facilities are coordinated with the university."],"image":{"src":"/images/community/campus-aerial.webp","alt":"Aerial view of the St. George’s University True Blue campus","historical":true}},"contact":{"heading":"Contact","body":"For anything the site does not answer, email the MSA directly.","email":"so-msa@sgu.edu","note":"Board members are students. Replies may take a few days during examination periods."}}$seed$::jsonb);
insert into public.page_texts (key, document) values ('prayer', $seed${"sections":[{"id":"times","shown":true},{"id":"jumuah","shown":true},{"id":"directions","shown":true},{"id":"gallery","shown":true},{"id":"facilities","shown":true},{"id":"helpers","shown":true}],"hero":{"eyebrow":"Worship at SGU","title":"Prayer & Musallah","description":"Daily iqamah times, Jumu’ah information, and everything you need to find the Musallah.","image":{"src":"/images/prayer/hero-musallah.webp","alt":"Inside the SGU Musallah, prayer rugs laid across the hall","focal_point":"50% 45%","historical":false}},"heading":"Daily Iqamah Times","schedule_note":"Congregation times set by the MSA; separate from calculated prayer start times.","no_schedule_note":"A current congregation schedule has not yet been published.","unavailable_note":"The schedule is temporarily unavailable. Please check with the MSA before travelling.","times":[]}$seed$::jsonb);
