insert into public.page_texts (key, document) values ('resources', $seed${"sections":[{"id":"library","shown":true},{"id":"archive","shown":true}],"hero":{"eyebrow":"Publication library","title":"Resources","description":"Newsletters, guides, and reference material published by the MSA."},"search_placeholder":"Search resources…","empty_message":"No resources match this search.","categories":["newsletter","infographic","guide","academic","faith","ramadan","incoming-students"],"items":[{"id":"newsletter-april-2026","title":"MSA Newsletter — April 2026","category":"newsletter","description":"Edition 7 of the MSA newsletter. Updates, reminders, and stories from the term.","updated_label":"Archive · April 2026","resource_url":"/documents/msa-newsletter-april-2026.pdf","pending_label":"Link coming soon","image":{"src":"/images/placeholder/editorial.svg","alt":"MSA newsletter cover","historical":false},"archived":true},{"id":"jumuah-guide","title":"Jumu’ah at SGU","category":"guide","description":"Where Jumu’ah is held, what time to arrive, and what to expect if it is your first time.","resource_url":"/prayer#jumuah","pending_label":"Link coming soon","image":{"src":"/images/resources/jumuah-notice.webp","alt":"MSA Jumu’ah prayer notice","historical":true}},{"id":"finding-the-musallah","title":"Finding the Musallah","category":"incoming-students","description":"A walking route from the Charter Hall bus stop, with step-by-step written directions.","resource_url":"/prayer#find-the-musallah","pending_label":"Link coming soon","image":{"src":"/images/prayer/musallah-route-poster.webp","alt":"The walking route toward the SGU Musallah","historical":false}},{"id":"community-events-archive","title":"MSA Community Events","category":"infographic","description":"A look at the socials, tournaments, and fundraisers the MSA has run at SGU.","updated_label":"Archive","resource_url":"/calendar","pending_label":"Link coming soon","image":{"src":"/images/resources/basketball-tournament.webp","alt":"MSA basketball tournament announcement","historical":true},"archived":true}]}$seed$::jsonb);
insert into public.page_texts (key, document) values ('get-involved', $seed${"sections":[{"id":"pathways","shown":true}],"hero":{"eyebrow":"Contribute","title":"Get Involved","description":"Every part of the MSA is run by students. These are the ways in."},"intro":"You do not need a title or a track record to contribute. Pick the pathway that fits the time you have, and MSA leadership will take it from there.","pathways":[{"id":"musallah-helper","number":"01","title":"Become a Musallah Helper","summary":"Keep the space ready for the community.","body":"Musallah helpers look after the day-to-day of the prayer space — tidying, restocking, setting up before Jumu’ah, and flagging anything that needs attention. It is the most direct way to serve people you will never meet.","icon":"help","form":"musallah_helper","steps":[],"fields":[]},{"id":"student-khutbah","number":"02","title":"Give a Student Khutbah","summary":"Share a khutbah with the Jumu’ah congregation.","body":"Students deliver khutbahs at SGU. Submit your interest and proposed topic. MSA leadership will follow up regarding preparation, review, and scheduling.","icon":"mic","form":"student_khutbah","steps":[{"id":"apply","label":"Apply","detail":"Send your interest and a proposed topic."},{"id":"prepare","label":"Prepare","detail":"Work on the khutbah with support from the board."},{"id":"review","label":"Review","detail":"MSA leadership reviews content and readiness."},{"id":"deliver","label":"Deliver","detail":"A date is scheduled once review is complete."}],"fields":[],"note":"Submitting the form is an expression of interest. It is not an approval or a confirmed date."},{"id":"host-halaqa","number":"03","title":"Host a Halaqa","summary":"Convene a gathering around something worth discussing.","body":"Halaqas at SGU have covered everything from tafsir to keeping faith through a clinical rotation. Tell us what you want to run and what help you need to run it.","icon":"halaqa","form":"host_halaqa","steps":[],"fields":["Topic","Proposed facilitator","Audience","Preferred timing","Assistance needed"]},{"id":"volunteer","number":"04","title":"Volunteer","summary":"Turn up for the events that need hands.","body":"Setup, registration, food, cleanup, photography — most MSA events need more people than the board has. Volunteering is the lowest-commitment way to be part of them.","icon":"volunteer","form":"volunteer","image":{"src":"/images/community/gathering-dusk.webp","alt":"MSA students gathered on the lawn at dusk above the campus","historical":true},"steps":[],"fields":[]},{"id":"mentor","number":"05","title":"Mentor an Incoming Student","summary":"Be the person you needed in your first term.","body":"Incoming students land on an island, in a new programme, often far from family. A mentor who has already done the first term makes a measurable difference.","icon":"mentor","form":"mentor","steps":[],"fields":[]},{"id":"support-ramadan","number":"06","title":"Support Ramadan","summary":"Help the month run for everyone on campus.","body":"Ramadan needs both hands and funding — iftars, Musallah setup, nightly programmes, and the supplies behind them.","icon":"moon","form":"ramadan_volunteer","steps":[],"fields":[]},{"id":"submit-idea","number":"07","title":"Submit an Idea","summary":"Propose something that does not exist yet.","body":"If there is a gap you keep noticing, describe it. Several of the MSA’s recurring programmes started as one student’s suggestion.","icon":"idea","form":"submit_idea","steps":[],"fields":[]},{"id":"incoming-student","number":"08","title":"Connect With an MSA Student","summary":"New to SGU and want to speak to someone first?","body":"If you are arriving soon and would rather talk to a student than read a page, we will connect you with someone in your programme.","icon":"message","form":"incoming_student","steps":[],"fields":[]}]}$seed$::jsonb);
insert into public.page_texts (key, document) values ('forms', $seed${"forms":{"musallah_helper":{"label":"Become a Musallah Helper","url":"https://forms.gle/9ZuhdAz6PXKReYW58","open":false,"closed_label":"Interest Form Coming Soon","description":"Help keep the Musallah welcoming, organized, and ready for the community."},"student_khutbah":{"label":"Give a Student Khutbah","url":"https://forms.gle/9ZuhdAz6PXKReYW58","open":false,"closed_label":"Interest Form Coming Soon","description":"Submit your interest and a proposed topic."},"host_halaqa":{"label":"Host a Halaqa","url":"https://forms.gle/9ZuhdAz6PXKReYW58","open":false,"closed_label":"Interest Form Coming Soon","description":"Propose a gathering and tell us what support you need."},"volunteer":{"label":"Volunteer","url":"https://forms.gle/9ZuhdAz6PXKReYW58","open":false,"closed_label":"Volunteer Form Coming Soon"},"mentor":{"label":"Become a Mentor","url":"https://forms.gle/9ZuhdAz6PXKReYW58","open":false,"closed_label":"Mentor Form Coming Soon"},"incoming_student":{"label":"Connect With an MSA Student","url":"https://forms.gle/9ZuhdAz6PXKReYW58","open":false,"closed_label":"Form Coming Soon"},"submit_idea":{"label":"Submit an Idea","url":"https://forms.gle/9ZuhdAz6PXKReYW58","open":false,"closed_label":"Idea Form Coming Soon"},"ramadan_volunteer":{"label":"Volunteer During Ramadan","url":"https://forms.gle/9ZuhdAz6PXKReYW58","open":false,"closed_label":"Volunteer Form Coming Soon"},"ramadan_donor":{"label":"Support Ramadan","url":"https://forms.gle/9ZuhdAz6PXKReYW58","open":false,"closed_label":"Donor Form Coming Soon"}}}$seed$::jsonb);
insert into public.page_texts (key, document) values ('faq', $seed${"sections":[{"id":"questions","shown":true}],"hero":{"eyebrow":"You asked, we answered","title":"Common Questions","description":"Practical answers about prayer, the Musallah, and getting involved."},"eyebrow":"You asked, we answered","heading":"Common Questions","items":[{"id":"musallah-location","question":"Where is the Musallah located?","answer":"The Musallah is a short walk from the Charter Hall bus stop. The Prayer & Musallah page has step-by-step written directions."},{"id":"jumuah-times","question":"What are the Jumu’ah times?","answer":"Jumu’ah is held weekly at the SGU Musallah. The current khutbah and iqamah times are on the Prayer & Musallah page, and are updated there whenever they change."},{"id":"separate-areas","question":"Are brothers’ and sisters’ areas separate?","answer":"Arrangements for the prayer areas are being confirmed with the university, and will be published on the Prayer & Musallah page as soon as they are settled."},{"id":"student-khutbah","question":"Can I give a khutbah as a student?","answer":"Yes. Submit your interest and a proposed topic through the Get Involved page. MSA leadership will follow up regarding preparation, review, and scheduling."},{"id":"get-involved","question":"How can I get involved in MSA?","answer":"Get Involved lists every pathway — Musallah helper, khutbah, halaqa, volunteering, mentoring, Ramadan support, and submitting your own idea. Each one links to its form."},{"id":"who-to-talk-to","question":"Who can I talk to if I need help?","answer":"The Support page lists MSA representatives you can reach out to. MSA representatives offer peer support and are not professional counselors; the page also points to professional university services."}]}$seed$::jsonb);
insert into public.page_texts (key, document) values ('donate', $seed${"eyebrow":"Giving at SGU MSA","title":"Support","emphasis":"our community","lede":"Thank you for wanting to support Muslim student life at SGU."}$seed$::jsonb);
insert into public.page_texts (key, document) values ('contact', $seed${"sections":[{"id":"card","shown":true},{"id":"visit","shown":true}],"eyebrow":"Contact & visit","title":"You’re welcome here","description":"Connect with the MSA, ask a question, or plan your first visit.","card":{"heading":"Get in touch","email_intro":"For community questions and current access information:","no_email":"Contact details will be published here."},"visit":{"heading":"Find the Musallah","body":"Follow the written directions on the Prayer & Musallah page. Exact map, parking, and accessibility details are awaiting confirmation.","link_label":"View directions"}}$seed$::jsonb);
insert into public.page_texts (key, document) values ('support', $seed${"sections":[{"id":"privacy","shown":true},{"id":"contacts","shown":true},{"id":"professional","shown":true}],"enabled":false,"prototype_notice":true,"prototype_label":"Proposed Student Support Service","governance_notice":"This service is proposed by the MSA and has not been established as a St. George’s University service. It is shown here to describe what the MSA would offer if approved.","hero":{"eyebrow":"Peer support","title":"Need someone to talk to?","description":"MSA can offer a familiar peer connection and help students find the right next step."},"privacy":{"heading":"Discreet & Respectful","body":"Conversations with MSA representatives are handled with discretion and respect. MSA representatives provide peer support and are not professional counselors. Safety concerns or applicable university obligations may require appropriate escalation."},"contacts":{"heading":"Who you can reach","note":"Contact details are published here once the board confirms them.","pending_label":"Contact information to be confirmed.","items":[{"id":"brothers-vp","role":"Brothers’ VP","description":"First point of contact for brothers on campus.","status":"details_pending"},{"id":"sisters-vp","role":"Sisters’ VP","description":"First point of contact for sisters on campus.","status":"details_pending"},{"id":"general-msa","role":"General MSA","description":"For anything that does not fit elsewhere, or if you would rather not choose.","status":"confirmed","email":"so-msa@sgu.edu"},{"id":"faculty-advisor","role":"Faculty Advisor","description":"A faculty member connected to the MSA.","status":"details_pending"}]},"professional":{"heading":"Professional SGU Support","body":"MSA peer support is not a substitute for professional care. St. George’s University provides services staffed by trained professionals.","pending_label":"Official SGU resources will be linked here following review.","items":[{"id":"psychological-services","name":"SGU Psychological Services","status":"details_pending"},{"id":"dean-of-students","name":"Dean of Students","status":"details_pending"},{"id":"emergency","name":"Campus emergency contact","status":"details_pending"}]}}$seed$::jsonb);
